                              "student_no":  "",
                              "student_name":  "",
                              "body":  "​When you understand all about the sun and all about the atmosphere and all about the rotation of the earth, you may still miss the radiance of the sunset. There is no substitute for the direct perception of the con­crete achievement of a thing in its actuality. We want concrete fact with a high light thrown on what is relevant to its preciousness.- AN Whitehead, Science and the Modern World",
