const DataHelper = {
  async loadData() {
    try {
      const res = await fetch('data/works.json');
      if (res.ok) { return await res.json(); }
    } catch (e) {
      console.log('HTTP fetch failed, using precompiled local offline data');
    }
    return window.YONGZHEN_RAW_DATA;
  }
};
